INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 19, 'theory', 'Квиз: хосты oVirt');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 0, 'Когда хост oVirt становится кандидатом на ограждение при настройках по умолчанию?', '["После первого же пропущенного ответа", "Когда он перешёл в обслуживание", "Когда подряд не меньше двух неудач и с первой прошло не меньше 60 секунд", "Когда на нём не осталось ни одной машины"]', 2, 'Нужны оба условия сразу: число подряд идущих неудач и время с первой из них. Так одиночный сбой не приводит к выключению хоста.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 1, 'Почему менеджер перезапускает HA-машины с упавшего хоста только после ограждения или ручного подтверждения?', '["Иначе две копии машины могли бы открыть один диск и испортить данные", "Потому что новые хосты нельзя использовать раньше", "Потому что ограждение ускоряет миграцию", "Потому что портал не показывает машины с упавшего хоста"]', 0, 'Менеджер не знает, действительно ли хост мёртв. Пока он мог остаться живым, запуск второй копии опасен; ограждение даёт уверенность, что старая копия остановлена.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 2, 'Чем статус NonOperational отличается от NonResponsive?', '["Это одно и то же", "NonOperational означает, что хост выключен администратором", "NonResponsive возникает только при обновлении", "При NonOperational хост на связи, но не соответствует требованиям, например нет сети или хранилища"]', 3, 'NonResponsive это потеря связи с хостом. NonOperational ставят хосту, который отвечает, но не годится для работы кластера.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 3, 'Какую задачу решает supervdsmd?', '["Принимает все команды менеджера по JSON-RPC", "Выполняет привилегированные действия от root: сеть, монтирование, устройства", "Хранит базу данных менеджера", "Запускает процессы QEMU без libvirt"]', 1, 'Команды принимает vdsmd под обычным пользователем, а всё, что требует прав root, он просит у supervdsmd.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 19, 4, 'Зачем нужна политика «пропускать ограждение, если потеряна связь с долей хостов кластера»?', '["Чтобы ускорить обновление кластера", "Чтобы не тратить память на проверки", "Если пропали сразу многие хосты, вероятно, сломалась сеть менеджера, и ограждать здоровые хосты нельзя", "Чтобы хосты не могли входить в обслуживание"]', 2, 'Массовая потеря связи чаще означает проблему на стороне менеджера или общей сети. Выключать из-за этого десятки живых хостов было бы катастрофой.');
